const requested = $json.season;
const month = $now.month;
const name = month <= 3 ? 'winter' : month <= 6 ? 'spring' : month <= 9 ? 'summer' : 'fall';
const season = requested === undefined || requested === null || requested === ''
  ? `${name}-${$now.year}`
  : String(requested).trim().toLowerCase();
if (!/^(spring|summer|fall|winter)-\d{4}$/.test(season)) {
  throw new Error(`Invalid season: ${season}`);
}
const deviceId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
  const random = Math.floor(Math.random() * 16);
  const value = character === 'x' ? random : (random & 0x3) | 0x8;
  return value.toString(16);
});
return [{ json: { season, device_id: deviceId } }];

const payload = $json;
const season = $('Prepare Discovery').first().json.season;
if (!Number.isInteger(payload.total) || payload.total < 1 || !Array.isArray(payload.data)) {
  throw new Error('Seasonal catalog has an invalid total or data list');
}
if (payload.total !== payload.data.length) {
  throw new Error(`Seasonal catalog pagination is incomplete: expected ${payload.total}, received ${payload.data.length}`);
}
const normalizeTitle = (value) => String(value).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const observedAt = $now.toISO();
const shows = [];
const seenKeys = new Set();
for (const item of payload.data) {
  if (!item || item.type !== 'series' || typeof item.id !== 'string' || !item.id.trim() || typeof item.title !== 'string' || !item.title.trim() || typeof item.slug_title !== 'string' || !item.slug_title.trim()) {
    throw new Error('Seasonal catalog contains a series with missing identity fields');
  }
  const showKey = normalizeTitle(item.title);
  if (!showKey || seenKeys.has(showKey)) continue;
  seenKeys.add(showKey);
  shows.push({
    show_key: showKey,
    title: item.title.replace(/\s+/g, ' ').trim(),
    url: `https://www.crunchyroll.com/series/${item.id}/${item.slug_title}`,
    season
  });
}
if (!shows.length) throw new Error(`Seasonal catalog for ${season} contained no series`);
const state = $getWorkflowStaticData('global');
if (state.contract_version !== undefined && state.contract_version !== 1) {
  throw new Error(`Unsupported discovery state contract: ${state.contract_version}`);
}
if (state.shows !== undefined && (!state.shows || Array.isArray(state.shows) || typeof state.shows !== 'object')) {
  throw new Error('Discovery state shows value must be an object');
}
state.contract_version = 1;
state.shows ??= {};
const current = shows.map((show) => {
  const previous = state.shows[show.show_key];
  const seenBefore = previous !== undefined;
  if (seenBefore && (!previous || typeof previous !== 'object')) {
    throw new Error(`Invalid discovery state for ${show.show_key}`);
  }
  state.shows[show.show_key] = {
    ...show,
    first_seen: seenBefore && typeof previous.first_seen === 'string' ? previous.first_seen : observedAt,
    last_seen: observedAt
  };
  return { ...state.shows[show.show_key], seen_before: seenBefore };
});
current.sort((left, right) => left.title.localeCompare(right.title));
return [{ json: {
  contract_version: 1,
  season,
  show_count: current.length,
  new_shows: current.filter((show) => !show.seen_before),
  seen_shows: current.filter((show) => show.seen_before)
} }];
